    int tribonacci(int n) {
        int prev_0 = 0;
        int prev_1 = 1;
        int prev_2 = 1;
        int curr=0;

        if(n==1 or n==2)
            return 1;

        for(int i=3; i<=n; i++){
            curr=prev_0+prev_1+prev_2;
            prev_0=prev_1;
            prev_1=prev_2;
            prev_2=curr;
        }

        return curr;
    }
};

class Solution:
    def tribonacci(self, n: int) -> int:
        if n < 2:
            return n
        if n == 2:
            return 1
        first = 0
        second = 1
        third = 1
        for i in range(3, n + 1):
            third = third + second + first
            second = third - second - first
            first = third - second - first
        return third

